import{_ as n,l as o,o as e,c as s,v as t,p as l,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"图灵机","description":"","frontmatter":{"title":"图灵机","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/turing-machine.md","filePath":"cs/turing-machine.md","lastUpdated":1789023840000}'),h={name:"cs/turing-machine.md"};function m(u,a,E,T,_,A){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="图灵机" tabindex="-1">图灵机 <a class="header-anchor" href="#图灵机" aria-label="Permalink to &quot;图灵机&quot;">​</a></h1><div class="epigraph"><p>有限控制器、一条无限格子带、一个读写头：每一步读格、改写、移一格、换状态；这是本补层对「过程」的标准模型。</p><footer>—— 据 Turing, On Computable Numbers, 1936；Sipser 整理</footer></div><p>上一课<a href="/cs/cyk-parsing">CYK</a>把 CFL 成员关在多项式判定里。Chomsky 0 型还没有机器。缺口不是再加强栈，而是<strong>图灵机（TM）</strong>：带子可双向改写、可往复，语言类变成递归可枚举。本课只钉单带确定 TM 与识别的定义；变体与论题是后两课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PDA 的栈不能改写已经埋住的符号，也不能把输入当草稿。TM：\\(Q,\\Sigma,\\Gamma,\\delta,q_0,q_{\\mathrm{acc}},q_{\\mathrm{rej}}\\)。带初始写着输入，其余空白。\\(\\delta(q,a)=(p,b,D)\\)。三种结局：接受、拒绝、永不停止。识别 \\(L\\)：对 \\(w\\in L\\) 必停在接受；对 \\(w\\notin L\\) 可拒绝或循环。判定还要求总停，那是下一单元。</p><p>不要从<a href="/cs/bit-as-distinction">比特</a>重讲存储：带格是字母表 \\(\\Gamma\\) 上的格子，已经是本课程第一课的串，只是长度在运行中可变。</p><h3 id="图灵机不是「一台电脑」" tabindex="-1">图灵机不是「一台电脑」 <a class="header-anchor" href="#图灵机不是「一台电脑」" aria-label="Permalink to &quot;图灵机不是「一台电脑」&quot;">​</a></h3><p>Turing 1936 的对象是可计算实数与判定问题，不是操作系统。有限控制对应程序，带对应工作空间。时钟、缓存、进程都在主干系统栈，本课不请回来。</p><p><span class="marginnote">Turing 原文用「自动机」扫描方格。Sipser 的三结局是课堂标准。后课 Church–Turing 才把「任何算法」对齐到这一模型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写一台认 \\(\\{a^nb^nc^n\\}\\) 的 TM：来回配对划掉，比 PDA 多的是能改输入。强调：存在 TM 识别，不等于我们能判定它是否对所有输入停下——那是停机问题。构造成表或状态图，本课不把 \\(\\delta\\) 的每一行写满。</p>',11)),(e(),l(c,null,{default:r(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%E5%86%99%E5%9C%A8%E5%B8%A6%E4%B8%8A%22%5D%20--%3E%20STEP%5B%22%E8%AF%BB%E6%94%B9%E7%A7%BB%E6%8D%A2%E6%80%81%22%5D%0A%20%20STEP%20--%3E%20ACC%5B%22%E6%8E%A5%E5%8F%97%E5%81%9C%22%5D%0A%20%20STEP%20--%3E%20REJ%5B%22%E6%8B%92%E7%BB%9D%E5%81%9C%22%5D%0A%20%20STEP%20--%3E%20LOOP%5B%22%E6%B0%B8%E4%B8%8D%E5%81%9C%E6%AD%A2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>主干组成课的<a href="/cs/fsm-control">FSM</a> 是有限状态控制；TM 的新资源是无界可改写带。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>配置 \\(uqv\\)：状态、头位置、带内容（有限非空白）。一步关系在配置上。语言 \\(L(M)\\) 是导致接受停的输入集。0 型文法与 TM 等价：生成对应枚举，识别对应半判定。本课登记，不写翻译。</p><p>时间、空间以后用「步数、扫过的格数」量；本课还没有复杂类。</p><p>空白符属于 \\(\\Gamma\\setminus\\Sigma\\)，输入不含空白这一约定让「输入结束」可观察。双向移动使 TM 能把输入当草稿纸：划掉、改写、把计数搬到带的另一侧。PDA 做不到改写已经埋住的栈符号。三种结局里，循环不是「错误输出」，而是识别与判定的分界，下一单元才切开。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证停机不可判定，不引入多带，不谈 RAM 机。也不把 TM 当编程练习环境。后课默认：谈到识别，即某 TM 的 \\(L(M)\\)；判定要总停。下一课多带、非确定、双向无限带与单带等价。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单带 TM：有限控制 + 可改写无限带；三种结局。</li><li>识别允许对否实例循环；CFL 做不到的语言从此可描述。</li><li>不是系统栈里的那台电脑。</li><li>出处：Turing, 1936；Sipser。</li></ul>',9))])}const P=n(h,[["render",m]]);export{B as __pageData,P as default};
